exec claude -p --model sonnet --strict-mcp-config --plugin-dir "${GESTALT_PLUGIN_PROSE_AUTHOR:?set GESTALT_PLUGIN_PROSE_AUTHOR to the prose-author plugin directory}" "$PROMPT"
